    }{
        {
            name: "valid pod spec",
            spec: &core.PodSpec{
                Containers: []core.Container{{Name: "test", Image: "test"}},
            },
        },
    }

    for _, tc := range successCases {
        t.Run(tc.name, func(t *testing.T) {
            errs := ValidatePodSpec(tc.spec, field.NewPath("spec"))
